window.kbPageData["views/entry/k-85d8698fca94eb62"] = {"key":"entry/k-85d8698fca94eb62","state":{"route":"entry/k-85d8698fca94eb62"},"node":{"id":"k-85d8698fca94eb62","mode":"k","title":"肯定前件","type":"原理与机制","domain":"形式逻辑","reading":"","intro":"","priority":100,"aliases":["充分条件成立可推出其结论"],"qs":["国考 2025 副省级 行测#115"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"当“如果P，那么Q”为真且前件P成立时，可以推出后件Q成立。","review":{"definition":"当“如果P，那么Q”为真且前件P成立时，可以推出后件Q成立。","explanation":"戊、己、庚至少有两人获奖，而庚只有一人，所以戊、己中至少有一人获奖，第（3）条的前件“乙、戊、己至少有1人获奖”随之成立。按原题，第（3）条的后件是“丁获奖而丙不获奖”，因此丁一定获奖，选D。解析第一步把这一后件写成了“丁获奖 且     丙获奖”，后续推理使用的是原题中的“丙不获奖”。","references":[],"evidence":"如果乙、戊、己至少有1人获奖，则丁获奖而丙不获奖。","disposition":"独立词条","basis":"据原题和解析编释。"}},"questions":{"国考 2025 副省级 行测#115":{"paper":"国考 2025 副省级 行测","n":115,"mod":"判断推理","src":["ffe12c35a46d4df574ec.pdf",22],"asrc":["ff0b352b44d417525086.pdf",37],"card":"a618b82e2d6466d4229956ec","links":[{"id":"k-85d8698fca94eb62","role":"解题依据","why":"一旦确认条件预测的前件成立，即可推出该预测给出的获奖结论。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-85d8698fca94eb62":[["国考 2025 副省级 行测#115"]]}};
